// Filter to only new replies we haven't processed.
// We track processed IDs in a static variable (resets on workflow restart,
// but that's fine — Supabase upsert handles deduplication).
const items = Array.isArray($json) ? $json : ($json.data || $json.emails || []);
const results = [];

for (const reply of items) {
  const fromEmail = (reply.from_email || reply.from || reply.sender || '').toLowerCase().trim();
  const body = reply.body || reply.text || reply.snippet || '';
  const subject = reply.subject || '';
  const receivedAt = reply.timestamp || reply.date || reply.received_at || new Date().toISOString();
  const messageId = reply.id || reply.message_id || '';

  if (!fromEmail || !body) continue;

  results.push({
    json: {
      from_email: fromEmail,
      body,
      subject,
      received_at: receivedAt,
      message_id: messageId
    }
  });
}

if (results.length === 0) {
  // Return empty to stop the workflow gracefully
  return [{ json: { _empty: true } }];
}

return results;

// Merge reply data with matched prospect
const reply = $('Has Replies?').item.json;
const prospects = $json;
const prospect = Array.isArray(prospects) ? prospects[0] : prospects;

if (!prospect || !prospect.id) {
  // No matching prospect found — skip
  return { json: { skip: true, reason: 'no matching prospect', from_email: reply.from_email } };
}

return {
  json: {
    skip: false,
    prospect_id: prospect.id,
    business_name: prospect.business_name,
    current_status: prospect.status,
    vertical: prospect.vertical,
    from_email: reply.from_email,
    reply_body: reply.body,
    reply_subject: reply.subject,
    received_at: reply.received_at,
    message_id: reply.message_id
  }
};

// Map classification to CRM status update
const data = $('Prospect Found?').item.json;
const raw = ($json.content?.[0]?.text || '').trim().toLowerCase();

// Normalize classification
const validTypes = ['positive_reply', 'booked', 'not_interested', 'unsubscribe', 'out_of_office', 'neutral'];
const classification = validTypes.find(t => raw.includes(t.replace('_', ' ')) || raw.includes(t)) || 'neutral';

// Map to CRM prospect status
const statusMap = {
  positive_reply: 'active_lead',
  booked: 'active_lead',
  not_interested: 'closed_lost',
  unsubscribe: 'do_not_contact',
  out_of_office: data.current_status, // don't change status for OOO
  neutral: data.current_status
};

const newStatus = statusMap[classification] || data.current_status;

return {
  json: {
    ...data,
    classification,
    new_status: newStatus,
    should_update: newStatus !== data.current_status
  }
};

